def f(g):
    bg=g[0][0]; H=len(g); W=len(g[0])
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]!=bg]
    rowocc={}
    for r,c in cells: rowocc.setdefault(r,set()).add(c)
    d=defaultdict(list)
    for r,c in cells: d[g[r][c]].append((r,c))
    out=[row[:] for row in g]
    for s,v in d.items():
        v.sort()
        cur=[v[0]]; runs=[]
        for p in v[1:]:
            q=cur[-1]
            if abs(p[0]-q[0])==abs(p[1]-q[1]): cur.append(p)
            else: runs.append(cur); cur=[p]
        runs.append(cur)
        for run in runs:
            if len(run)<2: continue
            dr,dc=run[1][0]-run[0][0],run[1][1]-run[0][1]
            # try forward from last cell
            rr,cc=run[-1][0]+dr,run[-1][1]+dc
            good=True
            while 0<=rr<H and 0<=cc<W and g[rr][cc]==bg:
                if cc in rowocc.get(rr,set()): good=False; break
                out[rr][cc]=s; rr+=dr; cc+=dc
            if good:
                # backward
                rr,cc=run[0][0]-dr,run[0][1]-dc
                while 0<=rr<H and 0<=cc<W and g[rr][cc]==bg:
                    if cc in rowocc.get(rr,set()): break
                    out[rr][cc]=s; rr-=dr; cc-=dc
    return out
